let loopFunction = () => {};

function setup() {
  createCanvas(920, 690, WEBGL);
	colorMode(HSB, 255);
  const gl = this._renderer.GL;

  const sh = baseMaterialShader().modify({
    'vertexDeclarations':`
      uniform float uExpand;
    `,
    'vec3 getLocalPosition':`(vec3 p){
      p += aNormal * uExpand;
      return p;
     }`
  });

  noStroke();

  //const positions = [[100,0,0],[0,100,0],[-100,0,0],[0,-100,0]];
	const positions = [[-75,-75,0],[75,-75,0],[-75,75,0],[75,75,0]];
  const axes = [];
  for(let i=0; i<4; i++){ axes.push(p5.Vector.random3D()); }

  const drawGeometry = () => {
    push();
    for(let i=0; i<4; i++){
      push();
      translate(...positions[i]);
      rotate(frameCount*TAU/80, axes[i]);
      fill(frameCount*.5%255,200,255);
      ellipsoid(50, 30, 70, 32);
      pop();
    }
    pop();
  }

  loopFunction = () => {
    orbitControl(1,1,1,{freeRotation:true});

    background(255);
    shader(sh);
    fill(frameCount*.5%255,255,128);
    sh.setUniform("uExpand", 0.1);
    noLights();
    scale(2);
    drawGeometry();

    gl.clear(gl.DEPTH_BUFFER_BIT);

    resetShader();
    ambientLight(160);
    directionalLight(0,0,160,-1,-1,-1);
    directionalLight(0,0,160,1,1,1);
    specularMaterial(64);
    fill(frameCount*.5%255, 200, 255);

    drawGeometry();
  }
}

function draw() {
  loopFunction();
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

